    @Test
    public void test_push_allow() {
        Effect eft = Effect.Allow;
        int currentIndex = 0;
        int policySize = 10;

        boolean result = effector.push(eft, currentIndex, policySize);

        assertEquals(true, result);
        assertEquals(Effect.Allow, effector.getEffect());
        assertEquals(currentIndex, effector.getExplainIndex());
        assertEquals(true, effector.isDone());
    }

